You assess retrieved reference tests for unit-test generation.
A generator must write a Hardhat (ethers 6, Mocha/Chai) unit-test suite for the TARGET Solidity contract below.
It receives example tests retrieved from a corpus of OTHER contracts. Such examples are never written for the target:
a different contract name is expected and is NOT a reason for a low rating. Judge only their value as a template.

Rate the RETRIEVED TEST:
2 = directly adaptable: it exercises a behaviour that the target also implements (same kind of operation, state change,
    access rule or revert condition); its setup, calls, assertions or revert checks could be reused after renaming.
1 = partially useful: it shows a generic testing pattern applicable to the target (e.g., access-control revert, event
    assertion, time manipulation, balance change, deployment with constructor arguments), but the specific behaviour it
    tests does not exist in the target.
0 = not useful: neither its behaviour nor its testing pattern applies to the target.

Give a reason of at most 30 words, then the rating.

TARGET CONTRACT:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract Counter {
    uint256 public count;
    address public immutable owner;

    constructor() { owner = msg.sender; }

    function increment() external { count += 1; }
    function decrement() external {
        require(count > 0, "underflow");
        count -= 1;
    }
    function reset() external {
        require(msg.sender == owner, "not owner");
        count = 0;
    }
}

RETRIEVED TEST:
// corpus-v2 pair simple-dex--lngdao (amm-dex, moderate)
// SimpleDEX.test.js: SimpleDEX > Access control > should reject non-owner addLiquidity
const { expect } = require("chai");
const { ethers } = require("hardhat");
let usdc;
let weth;
let dex;
let owner, user1, user2;
const RATE = BigInt("350000000") * ethers.parseUnits("1", 18);
// beforeEach of suite "SimpleDEX"
beforeEach(async function () {
    [owner, user1, user2] = await ethers.getSigners();

    const MockERC20Factory = await ethers.getContractFactory("MockERC20");
    usdc = await MockERC20Factory.deploy("Mock USDC", "USDC", 6);
    weth = await MockERC20Factory.deploy("Mock WETH", "WETH", 18);

    const SimpleDEXFactory = await ethers.getContractFactory("SimpleDEX");
    dex = await SimpleDEXFactory.deploy(
      await usdc.getAddress(),
      await weth.getAddress(),
      RATE
    );

    // Mint tokens to owner and add liquidity
    await usdc.mint(owner.address, ethers.parseUnits("500000", 6));
    await weth.mint(owner.address, ethers.parseUnits("500", 18));

    await usdc.approve(await dex.getAddress(), ethers.parseUnits("500000", 6));
    await weth.approve(await dex.getAddress(), ethers.parseUnits("500", 18));
    await dex.addLiquidity(await usdc.getAddress(), ethers.parseUnits("500000", 6));
    await dex.addLiquidity(await weth.getAddress(), ethers.parseUnits("500", 18));

    // Mint USDC to user1 for swapping
    await usdc.mint(user1.address, ethers.parseUnits("10000", 6));
    // Mint WETH to user2 for reverse swaps
    await weth.mint(user2.address, ethers.parseUnits("10", 18));
  })
it("should reject non-owner addLiquidity", async function () {
      await usdc.mint(user1.address, ethers.parseUnits("1000", 6));
      await usdc.connect(user1).approve(await dex.getAddress(), ethers.parseUnits("1000", 6));

      await expect(
        dex.connect(user1).addLiquidity(await usdc.getAddress(), ethers.parseUnits("1000", 6))
      ).to.be.revertedWith("Only owner");
    })


